<?php
namespace App\Models;use Illuminate\Database\Eloquent\Factories\HasFactory;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\SoftDeletes;
class AccessPoint extends Model{use HasFactory,SoftDeletes;protected $fillable=['floor_id','survey_area_id','name','identifier','vendor','model','management_ip','status','x_normalized','y_normalized','configured_client_limit'];protected function casts():array{return ['x_normalized'=>'decimal:6','y_normalized'=>'decimal:6'];}public function floor(){return $this->belongsTo(Floor::class);}public function surveyArea(){return $this->belongsTo(SurveyArea::class);}public function radios(){return $this->hasMany(AccessPointRadio::class);}public function loadSamples(){return $this->hasMany(ApLoadSample::class);}public function latestLoadSample(){return $this->hasOne(ApLoadSample::class)->latestOfMany('sampled_at');}}
